import novamind_api as nm
import json

print("=== Running Market Research ===")
success_count = 0
for i in range(15):
    try:
        res = nm.market.research_market()
        if 'discovered_group_id' in res:
            success_count += 1
            print(f"Success {success_count}: Discovered {res['discovered_group_id']}")
        else:
            print("No discovery.")
    except Exception as e:
        print(f"Error: {e}")

print("=== Current Market Overview ===")
print(json.dumps(nm.market.get_market_overview(), indent=2))

