import json
import novamind_api as nm

try:
    with open('all_insights.json', 'r') as f:
        cache = json.load(f)
except Exception:
    cache = {}

res = nm.query("SELECT group_id, info_level FROM group_info_levels")
db_groups = {r['group_id']: r['info_level'] for r in res['rows']}

print("Checking if cache is up-to-date:")
for gid, lvl in db_groups.items():
    if gid not in cache:
        print(f"  Group {gid} is missing in cache")
    elif cache[gid]['info_level'] != lvl:
        print(f"  Group {gid} in cache has level {cache[gid]['info_level']}, but DB has {lvl}")
    else:
        pass
print("Done checking.")

