import novamind_api as nm

res = nm.query("SELECT group_id FROM group_info_levels WHERE info_level >= 1")
discovered_groups = [r['group_id'] for r in res['rows']]

print("=== Cross-Group Referrals (leads per 1000 subs/day) ===")
for g in sorted(discovered_groups):
    ins = nm.market.get_group_insights(group_id=g)
    network = ins.get('network_influence', {})
    if network:
        # network is {target_group_id: rate} or similar? Let's check keys and values
        print(f"Group {g} network influence keys:", list(network.keys()))
        for k, v in network.items():
            if v > 0:
                print(f"  {g} -> {k}: {v:.4f}")

import novamind_api as nm

res = nm.query("SELECT group_id FROM group_info_levels WHERE info_level >= 1")
discovered_groups = [r['group_id'] for r in res['rows']]

print("=== Cross-Group Referrals ===")
for g in sorted(discovered_groups):
    ins = nm.market.get_group_insights(group_id=g)
    network = ins.get('network_influence', {})
    if network:
        outgoing = network.get('outgoing', {})
        incoming = network.get('incoming', {})
        print(f"Group {g}:")
        if outgoing:
            print("  Outgoing:")
            for target, rate in outgoing.items():
                print(f"    -> {target}: {rate}")
        if incoming:
            print("  Incoming:")
            for source, rate in incoming.items():
                print(f"    <- {source}: {rate}")

