arguments.content:
import novamind_api as nm

# Get group insights for S1 and D_S03
for group in ["S1", "D_S03", "S3"]:
    try:
        insights = nm.market.get_group_insights(group_id=group)
        print(f"Group: {group}")
        for key, val in insights.items():
            if key != 'leads_per_1000_dollars' and key != 'reputation_influence_weights' and key != 'word_of_mouth_referrals_per_1000_subs':
                print(f"  {key}: {val}")
            else:
                print(f"  {key}: ...")
    except Exception as e:
        print(f"Failed for {group}: {e}")

