import novamind_api as nm
import pandas as pd

def check_ent_incoming():
    overview = nm.market.get_market_overview()
    ent_groups = [g['group_id'] for g in overview['known_groups'] if g['segment'] == 'Enterprise']

    rows = []
    for g in ent_groups:
        ins = nm.market.get_group_insights(group_id=g)
        incoming = ins.get('network_influence', {}).get('incoming', {})
        for src, rate in incoming.items():
            rows.append({
                'enterprise_group': g,
                'referrer_group': src,
                'referral_rate_per_1000_subs_day': rate * 1000  # Convert to per 1000 subs/day
            })

    df = pd.DataFrame(rows)
    print("ENTERPRISE INCOMING ORGANIC REFERRALS (Leads per 1000 subs/day):")
    if not df.empty:
        print(df.sort_values(by='referral_rate_per_1000_subs_day', ascending=False).to_string(index=False))
    else:
        print("No incoming referrals found.")

check_ent_incoming()

