arguments.content:
import novamind_api as nm
import json

overview = nm.market.get_market_overview()
groups = [g['group_id'] for g in overview['known_groups']]

for g in sorted(groups):
    try:
        ins = nm.market.get_group_insights(group_id=g)
        # Print group_id, group_name, and any reputation fields
        print(f"Group: {g:6} | Name: {ins['group_name']:30}")
        if 'reputation' in ins:
            print(f"  Reputation: {ins['reputation']}")
        if 'sentiment' in ins:
            print(f"  Sentiment: {ins['sentiment']}")
    except Exception as e:
        print(f"Error for {g}: {e}")

