import novamind_api as nm
import json

def check_insights():
    groups = ['S1', 'D_S03', 'D_S04', 'S3']
    for g in groups:
        print(f"=== Group {g} ===")
        try:
            ins = nm.market.get_group_insights(group_id=g)
            print(json.dumps(ins, indent=2))
        except Exception as e:
            print(f"Error for {g}: {e}")

check_insights()

