arguments.command:
./novamind-operation python-c "
import novamind_api as nm
r = nm.query('SELECT day, amount FROM ledger')
cash_by_day = {}
for row in r['rows']:
    d = row['day']
    cash_by_day[d] = cash_by_day.get(d, 0) + row['amount']

cum_sum = 0
for d in range(386):
    cum_sum += cash_by_day.get(d, 0)
    if d % 7 == 0:
        if d % 35 == 0 or d > 350:
            print(f'Day {d:3d} (Week {d//7:2d}): ${cum_sum:,.2f}')
"

